    public static final int PHASE_COUNTDOWN = 1;
    public static final int PHASE_UPLOADING = 2;
    public static final int PHASE_PROCESSING = 3;
    public static final int PHASE_COMPLETE = 4;
    public static final int PHASE_REVIEW = 5;
    public static final int PHASE_ERROR = 6;

    public interface Listener {
        void onStateChanged();
    }

    private static final String PREFS = "ultracar_dexshot_status";
    private static final Handler MAIN = new Handler(Looper.getMainLooper());
    private static final CopyOnWriteArrayList<WeakReference<Listener>> LISTENERS = new CopyOnWriteArrayList<>();

    private static volatile int phase = PHASE_READY;
    private static volatile long deadlineAt = 0L;
    private static volatile String message = "";
    private static int generation = 0;

    private DexShotState() {}

    public static int getPhase() {
        return phase;
    }

    public static long getDeadlineAt() {
        return deadlineAt;
    }

    public static String getMessage() {
        return message;
    }

    public static void bind(Listener listener) {
        if (listener == null) return;
        if (phase == PHASE_READY) {
            // Keep READY on fresh bind unless restored in future
        }
        LISTENERS.add(new WeakReference<>(listener));
        listener.onStateChanged();
    }

    public static void unbind(Listener listener) {
        if (listener == null) return;
        for (WeakReference<Listener> ref : LISTENERS) {
            Listener l = ref.get();
            if (l == null || l == listener) {
                LISTENERS.remove(ref);
            }
        }
    }

    private static void notifyListeners() {
        MAIN.post(new Runnable() {
            @Override
            public void run() {
                for (WeakReference<Listener> ref : LISTENERS) {
                    Listener l = ref.get();
                    if (l == null) {
                        LISTENERS.remove(ref);
                    } else {
                        l.onStateChanged();
                    }
                }
            }
        });
    }

    public static synchronized void update(Context context, int nextPhase, String detail) {
        if (nextPhase != PHASE_COUNTDOWN) {
            generation++;
        }
        phase = nextPhase;
        message = detail != null ? detail : "";
        if (nextPhase != PHASE_COUNTDOWN) {
            deadlineAt = 0L;
        }
        if (context != null) {
            SharedPreferences sp = context.getApplicationContext().getSharedPreferences(PREFS, Context.MODE_PRIVATE);
            sp.edit()
                .putInt("phase", nextPhase)
                .putString("detail", message)
                .putLong("lastAt", System.currentTimeMillis())
                .apply();
        }
        notifyListeners();
    }

    public static synchronized void captured(final Context context) {
        final int gen = ++generation;
        phase = PHASE_COUNTDOWN;
        deadlineAt = System.currentTimeMillis() + 12000L;
        message = "Đã lưu ảnh; chờ 12 giây gom cuốc.";
        if (context != null) {
            context.getApplicationContext().getSharedPreferences(PREFS, Context.MODE_PRIVATE)
                .edit()
                .putLong("captureDeadlineAt", deadlineAt)
                .apply();
        }
        notifyListeners();
        final Context appCtx = context != null ? context.getApplicationContext() : null;
        MAIN.postDelayed(new Runnable() {
            @Override
            public void run() {
                synchronized (DexShotState.class) {
                    if (gen == generation && phase == PHASE_COUNTDOWN) {
                        update(appCtx, PHASE_UPLOADING, "Đang gửi ảnh lên PC01 đọc AI...");
                        if (appCtx != null) {
                            DexShotUploader.enqueue(appCtx);
                        }
                    }
                }
            }
        }, 12000L);
    }
}

package com.tigeriq.dexshot;

import android.content.Context;
import android.content.SharedPreferences;
import android.graphics.Bitmap;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.FileOutputStream;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public final class DexShotQueue {
    private static final String PREFS = "ultracar_dexshot_queue";
    private static final String KEY_PENDING_VISION = "pending_vision";
    private static final String KEY_PENDING_COMMIT = "pending_commit";
    private static final String KEY_VISION_PREFIX = "vision_";
    private static final int MAX_BYTES = 2600000;

    public static final class Item {
        public final String token;
        public final File file;

        public Item(String token, File file) {
            this.token = REDACTED;
            this.file = file;
        }
    }

    private DexShotQueue() {}

    public static File getQueueDir(Context context) {
        File dir = new File(context.getApplicationContext().getFilesDir(), "dexshot_queue");
        if (!dir.exists()) {
            dir.mkdirs();
        }
        return dir;
    }

    public static synchronized String enqueueBitmap(Context context, Bitmap bitmap) throws Exception {
        if (context == null || bitmap == null) {
            throw new IllegalArgumentException("Missing context or bitmap");
        }
        Bitmap working = bitmap;
        int w = bitmap.getWidth();
        int h = bitmap.getHeight();
        int maxDim = Math.max(w, h);
        if (maxDim > 1920) {
            float scale = 1920.0f / maxDim;
            working = Bitmap.createScaledBitmap(bitmap, Math.max(1, Math.round(w * scale)), Math.max(1, Math.round(h * scale)), true);
        }

        byte[] jpeg = null;
        int quality = 88;
        while (quality >= 55) {
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            working.compress(Bitmap.CompressFormat.JPEG, quality, baos);
            byte[] candidate = baos.toByteArray();
            if (candidate.length <= MAX_BYTES || quality <= 55) {
                jpeg = candidate;
                break;
            }
            quality -= 11;
        }
        if (working != bitmap) {
            working.recycle();
        }
        if (jpeg == null || jpeg.length == 0) {
            throw new IllegalStateException("Empty JPEG");
        }

        String token = "shot_" + System.currentTimeMillis() + "_" + (int) (Math.random() * 10000);
        File outFile = new File(getQueueDir(context), token + ".jpg");
        FileOutputStream fos = new FileOutputStream(outFile);
        try {
            fos.write(jpeg);
            fos.flush();
        } finally {
            fos.close();
        }

        SharedPreferences sp = context.getApplicationContext().getSharedPreferences(PREFS, Context.MODE_PRIVATE);
        Set<String> set = new HashSet<>(sp.getStringSet(KEY_PENDING_VISION, new HashSet<String>()));
        set.add(token);
        sp.edit().putStringSet(KEY_PENDING_VISION, set).apply();
        return token;
    }

    public static synchronized List<Item> pendingVision(Context context) {
        SharedPreferences sp = context.getApplicationContext().getSharedPreferences(PREFS, Context.MODE_PRIVATE);
        Set<String> set = sp.getStringSet(KEY_PENDING_VISION, new HashSet<String>());
        List<Item> items = new ArrayList<>();
        File dir = getQueueDir(context);
        for (String token : set) {
            File f = new File(dir, token + ".jpg");
            if (f.exists() && f.length() > 0) {
                items.add(new Item(token, f));
            }
        }
        Collections.sort(items, new Comparator<Item>() {
            @Override
            public int compare(Item a, Item b) {
                return Long.compare(a.file.lastModified(), b.file.lastModified());
            }
        });
        return items;
    }

    public static synchronized void markVisionDone(Context context, String token, String rawJson) {
        SharedPreferences sp = context.getApplicationContext().getSharedPreferences(PREFS, Context.MODE_PRIVATE);
        Set<String> visionSet = new HashSet<>(sp.getStringSet(KEY_PENDING_VISION, new HashSet<String>()));
        visionSet.remove(token);
        Set<String> commitSet = new HashSet<>(sp.getStringSet(KEY_PENDING_COMMIT, new HashSet<String>()));
        commitSet.add(token);
        sp.edit()
            .putStringSet(KEY_PENDING_VISION, visionSet)
            .putStringSet(KEY_PENDING_COMMIT, commitSet)
            .putString(KEY_VISION_PREFIX + token, rawJson)
            .apply();
    }

    public static synchronized List<Item> pendingCommit(Context context) {
        SharedPreferences sp = context.getApplicationContext().getSharedPreferences(PREFS, Context.MODE_PRIVATE);
        Set<String> set = sp.getStringSet(KEY_PENDING_COMMIT, new HashSet<String>());
        List<Item> items = new ArrayList<>();
        File dir = getQueueDir(context);
        for (String token : set) {
            File f = new File(dir, token + ".jpg");
            if (f.exists() && f.length() > 0) {
                items.add(new Item(token, f));
            }
        }
        Collections.sort(items, new Comparator<Item>() {
            @Override
            public int compare(Item a, Item b) {
                return Long.compare(a.file.lastModified(), b.file.lastModified());
            }
        });
        return items;
    }

    public static synchronized String readVision(Context context, String token) {
        SharedPreferences sp = context.getApplicationContext().getSharedPreferences(PREFS, Context.MODE_PRIVATE);
        return sp.getString(KEY_VISION_PREFIX + token, null);
    }

    public static synchronized void markCommitted(Context context, String token) {
        SharedPreferences sp = context.getApplicationContext().getSharedPreferences(PREFS, Context.MODE_PRIVATE);
        Set<String> visionSet = new HashSet<>(sp.getStringSet(KEY_PENDING_VISION, new HashSet<String>()));
        visionSet.remove(token);
        Set<String> commitSet = new HashSet<>(sp.getStringSet(KEY_PENDING_COMMIT, new HashSet<String>()));
        commitSet.remove(token);
        sp.edit()
            .putStringSet(KEY_PENDING_VISION, visionSet)
            .putStringSet(KEY_PENDING_COMMIT, commitSet)
            .remove(KEY_VISION_PREFIX + token)
            .apply();
        File f = new File(getQueueDir(context), token + ".jpg");
        if (f.exists()) {
            f.delete();
        }
    }
}

package com.tigeriq.dexshot;

import android.content.Context;
import android.os.Handler;
import android.os.Looper;
import android.util.Log;
import android.webkit.CookieManager;
import java.io.BufferedReader;
import java.io.ByteArrayOutputStream;
import java.io.DataOutputStream;
import java.io.File;
import java.io.FileInputStream;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import org.json.JSONArray;
import org.json.JSONObject;

public final class DexShotUploader {
    private static final String TAG = "UltraCarDexShot";
    public static final String DIRECT_ORIGIN = "https://pc01.tail35d2f3.ts.net:8443";
    public static final String ORIGIN = "https://driver.tigeriq.io.vn";
    private static final int CHUNK_SIZE = 262144;
    private static final ExecutorService EXECUTOR = Executors.newSingleThreadExecutor();
    private static final Handler MAIN = new Handler(Looper.getMainLooper());

    private DexShotUploader() {}

    public static boolean hasSessionCookie() {
        try {
            CookieManager cm = CookieManager.getInstance();
            String c1 = cm.getCookie(DIRECT_ORIGIN);
            if (c1 != null && !c1.trim().isEmpty()) return true;
            String c2 = cm.getCookie(ORIGIN);
            return c2 != null && !c2.trim().isEmpty();
        } catch (Throwable t) {
            return false;
        }
    }

    public static void enqueue(final Context context) {
        if (context == null) return;
        final Context appCtx = context.getApplicationContext();
        EXECUTOR.execute(new Runnable() {
            @Override
            public void run() {
                runPipeline(appCtx);
            }
        });
    }

    private static String[] authenticatedTransport() {
        try {
            CookieManager cm = CookieManager.getInstance();
            String directCookie = cm.getCookie(DIRECT_ORIGIN);
            if (directCookie != null && !directCookie.trim().isEmpty()) {
                try {
                    HttpURLConnection conn = (HttpURLConnection) new URL(DIRECT_ORIGIN + "/api/pc01-device-session").openConnection();
                    conn.setInstanceFollowRedirects(false);
                    conn.setRequestMethod("GET");
                    conn.setConnectTimeout(3500);
                    conn.setReadTimeout(4000);
                    conn.setRequestProperty("Cookie", directCookie);
                    conn.setRequestProperty("Origin", DIRECT_ORIGIN);
                    int code = conn.getResponseCode();
                    String body = readStream(code == 200 ? conn.getInputStream() : null, 1200);
                    conn.disconnect();
                    if (code == 200) {
                        JSONObject json = new JSONObject(body);
                        if (json.optBoolean("ok") && "pc01".equals(json.optString("server"))) {
                            return new String[]{DIRECT_ORIGIN, directCookie};
                        }
                    }
                } catch (Throwable ignored) {}
            }
            String originCookie = cm.getCookie(ORIGIN);
            if (originCookie != null && !originCookie.trim().isEmpty()) {
                return new String[]{ORIGIN, originCookie};
            }
        } catch (Throwable t) {
            Log.w(TAG, "Auth check failed", t);
        }
        return null;
    }

    private static void runPipeline(final Context context) {
        try {
            List<DexShotQueue.Item> pending = DexShotQueue.pendingVision(context);
            List<DexShotQueue.Item> pendingCommits = DexShotQueue.pendingCommit(context);
            if (pending.isEmpty() && pendingCommits.isEmpty()) {
                return;
            }
            String[] transport = authenticatedTransport();
            if (transport == null) {
                DexShotState.update(context, DexShotState.PHASE_ERROR, "Cần đăng nhập TigerIQ AI (nhấn giữ nút T để đăng nhập).");
                return;
            }
            String baseUrl = transport[0];
            String cookies = transport[1];

            if (!pending.isEmpty()) {
                List<DexShotQueue.Item> batch = new ArrayList<>();
                long totalBytes = 0;
                for (DexShotQueue.Item item : pending) {
                    if (batch.size() >= 4) break;
                    long len = item.file.length();
                    if (len <= 0 || len > 2800000L) continue;
                    if (!batch.isEmpty() && totalBytes + len > 2800000L) break;
                    batch.add(item);
                    totalBytes += len;
                }
                if (batch.isEmpty()) {
                    DexShotState.update(context, DexShotState.PHASE_ERROR, "Ảnh quá lớn hoặc trống.");
                    return;
                }

                JSONArray imagesMeta = new JSONArray();
                List<byte[]> imageBytesList = new ArrayList<>();
                StringBuilder reqIdBuilder = new StringBuilder();
                for (int i = 0; i < batch.size(); i++) {
                    DexShotQueue.Item item = batch.get(i);
                    byte[] bytes = readFileBytes(item.file);
                    imageBytesList.add(bytes);
                    imagesMeta.put(new JSONObject()
                        .put("imageId", "photo_" + (i + 1))
                        .put("imageHash", sha256(bytes))
                        .put("mimeType", "image/jpeg")
                        .put("byteLength", bytes.length));
                    if (i > 0) reqIdBuilder.append("|");
                    reqIdBuilder.append(item.token);
                }

                String requestId = "driver_" + take(sha256(reqIdBuilder.toString().getBytes(StandardCharsets.UTF_8)), 40);
                JSONObject metaObj = new JSONObject()
                    .put("requestId", requestId)
                    .put("images", imagesMeta)
                    .put("context", new JSONObject()
                        .put("forcedApp", "Auto")
                        .put("expectedScreens", imageBytesList.size())
                        .put("batchEvidence", imageBytesList.size() > 1)
                        .put("sameTrip", false)
                        .put("recoverBeforeSend", false)
                        .put("clientSentAtMs", System.currentTimeMillis()));
                byte[] metaBytes = metaObj.toString().getBytes(StandardCharsets.UTF_8);

                ByteArrayOutputStream baos = new ByteArrayOutputStream(metaBytes.length + 4 + (int) totalBytes);
                DataOutputStream dos = new DataOutputStream(baos);
                dos.writeInt(metaBytes.length);
                dos.write(metaBytes);
                for (byte[] b : imageBytesList) {
                    dos.write(b);
                }
                dos.flush();
                byte[] payload = baos.toByteArray();

                DexShotState.update(context, DexShotState.PHASE_UPLOADING, "Đang tải " + batch.size() + " ảnh lên PC01...");
                int parts = (payload.length + CHUNK_SIZE - 1) / CHUNK_SIZE;
                String stageUrl = baseUrl + "/api/analyze-trip-multi?stage=1&requestId=" + requestId;
                for (int p = 0; p < parts; p++) {
                    int start = p * CHUNK_SIZE;
                    int end = Math.min(start + CHUNK_SIZE, payload.length);
                    byte[] chunk = new byte[end - start];
                    System.arraycopy(payload, start, chunk, 0, chunk.length);
                    String chunkHash = sha256(chunk);
                    String partUrl = stageUrl + "&part=" + p + "&parts=" + parts;
                    if (!postBinary(partUrl, cookies, baseUrl, requestId, chunkHash, chunk)) {
                        DexShotState.update(context, DexShotState.PHASE_ERROR, "Lỗi tải ảnh lên PC01 (chunk " + p + ").");
                        return;
                    }
                }
                if (!postBinary(stageUrl + "&finalize=1&parts=" + parts, cookies, baseUrl, requestId, null, new byte[0])) {
                    DexShotState.update(context, DexShotState.PHASE_ERROR, "PC01 chưa xác nhận đủ ảnh.");
                    return;
                }

                DexShotState.update(context, DexShotState.PHASE_PROCESSING, "PC01 đã nhận ảnh · Gemini đang đọc AI...");
                JSONObject ocrReq = new JSONObject()
                    .put("requestId", requestId)
                    .put("uploadId", requestId)
                    .put("forcedApp", "Auto")
                    .put("expectedScreens", imageBytesList.size())
                    .put("batchEvidence", imageBytesList.size() > 1)
                    .put("sameTrip", false)
                    .put("recoverBeforeSend", false)
                    .put("clientSentAtMs", System.currentTimeMillis());
                HttpResult ocrRes = postJson(baseUrl + "/api/analyze-trip-multi", cookies, baseUrl, requestId, ocrReq.toString(), 110000);
                if (ocrRes.code < 200 || ocrRes.code >= 300 || !ocrRes.json.optBoolean("success")) {
                    DexShotState.update(context, DexShotState.PHASE_ERROR, "Lỗi AI đọc ảnh (HTTP " + ocrRes.code + ").");
                    return;
                }

                List<JSONObject> raws = new ArrayList<>();
                JSONArray imageBatch = ocrRes.json.optJSONArray("imageBatch");
                if (batch.size() == 1) {
                    JSONObject raw = ocrRes.json.optJSONObject("data");
                    if (raw == null && imageBatch != null && imageBatch.length() > 0) {
                        JSONObject first = imageBatch.optJSONObject(0);
                        if (first != null && "photo_1".equals(first.optString("imageId"))) {
                            raw = first.optJSONObject("raw");
                        }
                    }
                    if (raw == null) {
                        DexShotState.update(context, DexShotState.PHASE_ERROR, "AI trả kết quả ảnh không hợp lệ.");
                        return;
                    }
                    raws.add(raw);
                } else {
                    if (imageBatch == null || imageBatch.length() != batch.size()) {
                        DexShotState.update(context, DexShotState.PHASE_ERROR, "AI trả kết quả nhóm ảnh không khớp.");
                        return;
                    }
                    for (int i = 0; i < imageBatch.length(); i++) {
                        JSONObject entry = imageBatch.optJSONObject(i);
                        JSONObject raw = entry != null ? entry.optJSONObject("raw") : null;
                        if (raw == null) {
                            DexShotState.update(context, DexShotState.PHASE_ERROR, "Thiếu dữ liệu OCR ảnh #" + (i + 1));
                            return;
                        }
                        raws.add(raw);
                    }
                }
                for (int i = 0; i < batch.size(); i++) {
                    DexShotQueue.markVisionDone(context, batch.get(i).token, raws.get(i).toString());
                }
            }

            // Commit pending
            List<DexShotQueue.Item> toCommit = DexShotQueue.pendingCommit(context);
            if (toCommit.isEmpty()) return;

            JSONObject commitBody;
            if (toCommit.size() == 1) {
                DexShotQueue.Item item = toCommit.get(0);
                String rawStr = DexShotQueue.readVision(context, item.token);
                if (rawStr == null) return;
                String reqId = "driver_" + take(sha256(item.token.getBytes(StandardCharsets.UTF_8)), 40);
                commitBody = new JSONObject()
                    .put("requestId", reqId)
                    .put("imageHash", sha256(readFileBytes(item.file)))
                    .put("raw", new JSONObject(rawStr));
            } else {
                JSONArray arr = new JSONArray();
                StringBuilder idBuilder = new StringBuilder();
                String lastHash = "";
                for (int i = 0; i < toCommit.size(); i++) {
                    DexShotQueue.Item item = toCommit.get(i);
                    String rawStr = DexShotQueue.readVision(context, item.token);
                    if (rawStr == null) continue;
                    String h = sha256(readFileBytes(item.file));
                    lastHash = h;
                    arr.put(new JSONObject()
                        .put("imageHash", h)
                        .put("capturedAt", item.file.lastModified())
                        .put("raw", new JSONObject(rawStr)));
                    if (i > 0) idBuilder.append("|");
                    idBuilder.append(item.token);
                }
                String reqId = "driver_" + take(sha256(idBuilder.toString().getBytes(StandardCharsets.UTF_8)), 40);
                commitBody = new JSONObject()
                    .put("requestId", reqId)
                    .put("imageHash", lastHash)
                    .put("images", arr);
            }

            HttpResult commitRes = postJson(baseUrl + "/api/native-vision/commit", cookies, baseUrl, null, commitBody.toString(), 24000);
            if (commitRes.code == 200 && commitRes.json.optBoolean("ok") && commitRes.json.optBoolean("archiveVerified")) {
                boolean committed = commitRes.json.optBoolean("committed");
                boolean provisional = committed && commitRes.json.optBoolean("provisional");
                for (DexShotQueue.Item item : toCommit) {
                    DexShotQueue.markCommitted(context, item.token);
                }
                if (committed && !provisional) {
                    DexShotState.update(context, DexShotState.PHASE_COMPLETE, "PC01 xác nhận đã ghi cuốc.");
                    MAIN.postDelayed(new Runnable() {
                        @Override
                        public void run() {
                            if (DexShotState.getPhase() == DexShotState.PHASE_COMPLETE) {
                                DexShotState.update(context, DexShotState.PHASE_READY, "");
                            }
                        }
                    }, 2500L);
                } else if (provisional) {
                    DexShotState.update(context, DexShotState.PHASE_REVIEW, "Đã lưu cuốc TẠM · chụp tiếp màn thu nhập/KM để hoàn tất.");
                } else {
                    String reason = commitRes.json.optString("reason", "REVIEW_REQUIRED");
                    DexShotState.update(context, DexShotState.PHASE_REVIEW, mapReason(reason));
                }
            } else {
                DexShotState.update(context, DexShotState.PHASE_ERROR, "PC01 chưa xác nhận ghi cuốc (HTTP " + commitRes.code + ").");
            }
        } catch (Throwable t) {
            Log.e(TAG, "Pipeline error", t);
            DexShotState.update(context, DexShotState.PHASE_ERROR, "Lỗi xử lý: " + t.getMessage());
        }
    }

    private static String mapReason(String reason) {
        if (reason == null) return "Ảnh đã xử lý nhưng chưa đủ chứng cứ tự ghi cuốc.";
        switch (reason) {
            case "MISSING_ROUTE": return "Thiếu điểm đón hoặc điểm trả; chụp màn tuyến cuốc.";
            case "NOT_COMPLETED_TRIP_SCREEN": return "Chưa thấy cuốc hoàn tất; chụp màn kết thúc chuyến.";
            case "MISSING_PAYMENT": return "Thiếu phương thức thanh toán; chụp màn thanh toán.";
            case "MISSING_NET": return "Thiếu thu nhập ròng; chụp màn thu nhập.";
            case "TRIP_DATE_REQUIRES_REVIEW": return "Ngày cuốc không khớp hôm nay; ảnh cần đối chiếu.";
            case "NO_VERIFIED_TRIP_CODE": return "Ảnh thiếu mã cuốc chính xác; chụp màn có mã cuốc.";
            case "MISSING_KM": return "Thiếu KM chính xác; chụp màn có quãng đường.";
            case "RAW_EVIDENCE_INSUFFICIENT": return "Ảnh mờ hoặc Gemini chưa đọc đủ; chụp rõ màn chi tiết.";
            case "OPEN_SON_SHIFT_REQUIRED": return "Chưa mở ca Sơn; cần mở ca trước khi ghi cuốc.";
            case "SETTLED_DAY_LOCKED": return "Ngày đã quyết toán, không thể tự ghi cuốc.";
            default: return "Ảnh đã đọc nhưng chưa đủ bằng chứng tự ghi cuốc.";
        }
    }

    private static boolean postBinary(String urlStr, String cookies, String origin, String reqId, String chunkHash, byte[] data) {
        HttpURLConnection conn = null;
        try {
            conn = (HttpURLConnection) new URL(urlStr).openConnection();
            conn.setRequestMethod("POST");
            conn.setDoOutput(true);
            conn.setConnectTimeout(15000);
            conn.setReadTimeout(30000);
            conn.setFixedLengthStreamingMode(data.length);
            conn.setRequestProperty("Content-Type", "application/octet-stream");
            conn.setRequestProperty("Cookie", cookies);
            conn.setRequestProperty("Origin", origin);
            if (reqId != null) conn.setRequestProperty("x-vision-request-id", reqId);
            if (chunkHash != null) conn.setRequestProperty("x-vision-chunk-sha256", chunkHash);
            OutputStream os = conn.getOutputStream();
            os.write(data);
            os.flush();
            os.close();
            int code = conn.getResponseCode();
            String body = readStream(code >= 200 && code < 300 ? conn.getInputStream() : conn.getErrorStream(), 1800);
            return code == 200 && new JSONObject(body).optBoolean("uploaded");
        } catch (Throwable t) {
            Log.w(TAG, "postBinary failed", t);
            return false;
        } finally {
            if (conn != null) conn.disconnect();
        }
    }

    private static final class HttpResult {
        final int code;
        final JSONObject json;
        HttpResult(int code, JSONObject json) {
            this.code = code;
            this.json = json;
        }
    }

    private static HttpResult postJson(String urlStr, String cookies, String origin, String reqId, String bodyStr, int readTimeout) {
        HttpURLConnection conn = null;
        try {
            conn = (HttpURLConnection) new URL(urlStr).openConnection();
            conn.setRequestMethod("POST");
            conn.setDoOutput(true);
            conn.setConnectTimeout(15000);
            conn.setReadTimeout(readTimeout);
            conn.setRequestProperty("Content-Type", "application/json");
            conn.setRequestProperty("Cookie", cookies);
            conn.setRequestProperty("Origin", origin);
            if (reqId != null) conn.setRequestProperty("x-vision-request-id", reqId);
            byte[] bytes = bodyStr.getBytes(StandardCharsets.UTF_8);
            OutputStream os = conn.getOutputStream();
            os.write(bytes);
            os.flush();
            os.close();
            int code = conn.getResponseCode();
            String resp = readStream(code >= 200 && code < 300 ? conn.getInputStream() : conn.getErrorStream(), 300000);
            return new HttpResult(code, new JSONObject(resp));
        } catch (Throwable t) {
            Log.w(TAG, "postJson failed", t);
            return new HttpResult(-1, new JSONObject());
        } finally {
            if (conn != null) conn.disconnect();
        }
    }

    private static String readStream(InputStream is, int maxChars) {
        if (is == null) return "{}";
        try (BufferedReader br = new BufferedReader(new InputStreamReader(is, StandardCharsets.UTF_8))) {
            StringBuilder sb = new StringBuilder();
            char[] buf = new char[4096];
            int n;
            while ((n = br.read(buf)) != -1) {
                sb.append(buf, 0, n);
                if (sb.length() >= maxChars) break;
            }
            String s = sb.toString();
            return s.isEmpty() ? "{}" : s;
        } catch (Throwable t) {
            return "{}";
        }
    }

    private static byte[] readFileBytes(File f) throws Exception {
        try (FileInputStream fis = new FileInputStream(f);
             ByteArrayOutputStream baos = new ByteArrayOutputStream((int) f.length())) {
            byte[] buf = new byte[8192];
            int n;
            while ((n = fis.read(buf)) != -1) {
                baos.write(buf, 0, n);
            }
            return baos.toByteArray();
        }
    }

    private static String sha256(byte[] data) throws Exception {
        byte[] digest = MessageDigest.getInstance("SHA-256").digest(data);
        StringBuilder sb = new StringBuilder(digest.length * 2);
        for (byte b : digest) {
            sb.append(String.format("%02x", b & 0xff));
        }
        return sb.toString();
    }

    private static String take(String s, int n) {
        return s.length() <= n ? s : s.substring(0, n);
    }
}

package com.tigeriq.dexshot;

import android.app.Activity;
