public final class DexShotLoginActivity extends Activity {
    private WebView webView;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        LinearLayout root = new LinearLayout(this);
        root.setOrientation(LinearLayout.VERTICAL);
        root.setBackgroundColor(0xFF0B1416);

        LinearLayout topBar = new LinearLayout(this);
        topBar.setOrientation(LinearLayout.HORIZONTAL);
        topBar.setGravity(Gravity.CENTER_VERTICAL);
        topBar.setPadding(24, 16, 24, 16);
        topBar.setBackgroundColor(0xFF004E45);

        TextView title = new TextView(this);
        title.setText("Đăng nhập TigerIQ AI (Nút T)");
        title.setTextColor(Color.WHITE);
        title.setTextSize(16f);
        LinearLayout.LayoutParams titleLp = new LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f);
        topBar.addView(title, titleLp);

        Button doneBtn = new Button(this);
        doneBtn.setText("Xong");
        doneBtn.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                try {
                    CookieManager.getInstance().flush();
                } catch (Throwable ignored) {}
                if (DexShotUploader.hasSessionCookie()) {
                    DexShotState.update(DexShotLoginActivity.this, DexShotState.PHASE_READY, "");
                    Toast.makeText(DexShotLoginActivity.this, "Đã lưu phiên đăng nhập TigerIQ AI.", Toast.LENGTH_SHORT).show();
                }
                finish();
            }
        });
        topBar.addView(doneBtn);
        root.addView(topBar, new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT));

        webView = new WebView(this);
        CookieManager.getInstance().setAcceptCookie(true);
        CookieManager.getInstance().setAcceptThirdPartyCookies(webView, true);
        WebSettings ws = webView.getSettings();
        ws.setJavaScriptEnabled(true);
        ws.setDomStorageEnabled(true);
        webView.setWebViewClient(new WebViewClient());
        webView.loadUrl(DexShotUploader.ORIGIN + "/");
        root.addView(webView, new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, 0, 1f));

        setContentView(root);
    }

    @Override
    protected void onDestroy() {
        try {
            CookieManager.getInstance().flush();
        } catch (Throwable ignored) {}
        if (webView != null) {
            webView.destroy();
        }
        super.onDestroy();
    }
}

package com.tigeriq.dexshot;

import android.app.Notification;
import android.app.NotificationChannel;
import android.app.NotificationManager;
import android.app.Service;
import android.content.Context;
import android.content.Intent;
import android.graphics.Bitmap;
import android.graphics.PixelFormat;
import android.hardware.display.DisplayManager;
import android.hardware.display.VirtualDisplay;
import android.media.Image;
import android.media.ImageReader;
import android.media.projection.MediaProjection;
import android.media.projection.MediaProjectionManager;
import android.os.Build;
import android.os.Handler;
import android.os.HandlerThread;
import android.os.IBinder;
import android.os.Looper;
import android.util.DisplayMetrics;
import android.util.Log;
import android.view.Display;
import android.widget.Toast;
import java.nio.ByteBuffer;
import java.util.concurrent.atomic.AtomicBoolean;

public final class DexShotCaptureService extends Service {
    private static final String TAG = "DexShotCaptureSvc";
    private static final String CHANNEL_ID = "ultracar_dexshot_capture";
    private static final int NOTIFICATION_ID = 7319;
    private static final String SAMSUNG_DESKTOP_CATEGORY = "com.samsung.android.hardware.display.category.DESKTOP";

    public static final String ACTION_START = "com.tigeriq.dexshot.START";
    public static final String ACTION_CAPTURE = "com.tigeriq.dexshot.CAPTURE";
    public static final String ACTION_STOP = "com.tigeriq.dexshot.STOP";
    public static final String EXTRA_RESULT_CODE = "resultCode";
    public static final String EXTRA_RESULT_DATA = "resultData";
    public static final String EXTRA_AUTO_CAPTURE = "autoCapture";

    private static volatile boolean projectionReady = false;
    private static volatile DexShotCaptureService activeService = null;

    private final Handler mainHandler = new Handler(Looper.getMainLooper());
    private HandlerThread workerThread;
    private Handler worker;
    private MediaProjection projection;
    private VirtualDisplay virtualDisplay;
    private ImageReader imageReader;
    private final AtomicBoolean captureRequested = new AtomicBoolean(false);
    private final Object frameLock = new Object();
    private Bitmap cachedFrame;
    private long lastFrameAt = 0L;
    private int width = 1920;
    private int height = 1080;
    private int density = 240;

    public static boolean isProjectionReady() {
        return projectionReady && activeService != null;
    }

    public static void captureOrRequest(Context context) {
        if (context == null) return;
        if (!DexShotUploader.hasSessionCookie()) {
            DexShotState.update(context, DexShotState.PHASE_ERROR, "Cần đăng nhập TigerIQ AI.");
            Intent login = new Intent(context, DexShotLoginActivity.class);
            login.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
            context.startActivity(login);
            return;
        }
        if (isProjectionReady()) {
            Intent i = new Intent(context, DexShotCaptureService.class);
            i.setAction(ACTION_CAPTURE);
            context.startService(i);
        } else {
            Intent req = new Intent(context, DexShotProjectionActivity.class);
            req.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
            context.startActivity(req);
        }
    }

    @Override
    public IBinder onBind(Intent intent) {
        return null;
    }

    @Override
    public void onCreate() {
        super.onCreate();
        activeService = this;
        workerThread = new HandlerThread("DexShotWorker");
        workerThread.start();
        worker = new Handler(workerThread.getLooper());
        ensureChannel();
    }

    @Override
    public int onStartCommand(Intent intent, int flags, int startId) {
        if (intent == null || intent.getAction() == null) {
            return START_NOT_STICKY;
        }
        String action = intent.getAction();
        if (ACTION_START.equals(action)) {
            startProjection(intent);
        } else if (ACTION_CAPTURE.equals(action)) {
            requestCapture();
        } else if (ACTION_STOP.equals(action)) {
            stopSelfSafely();
        }
        return START_NOT_STICKY;
    }

    private void startProjection(Intent intent) {
        Notification notif = buildNotification("UltraCar đang sẵn sàng chụp AI");
        if (Build.VERSION.SDK_INT >= 29) {
            startForeground(NOTIFICATION_ID, notif, 32);
        } else {
            startForeground(NOTIFICATION_ID, notif);
        }

        if (projectionReady && projection != null) {
            if (intent.getBooleanExtra(EXTRA_AUTO_CAPTURE, false)) {
                requestCapture();
            }
            return;
        }

        int resultCode = intent.getIntExtra(EXTRA_RESULT_CODE, 0);
        Intent resultData = Build.VERSION.SDK_INT >= 33
            ? intent.getParcelableExtra(EXTRA_RESULT_DATA, Intent.class)
            : (Intent) intent.getParcelableExtra(EXTRA_RESULT_DATA);

        if (resultData == null) {
            DexShotState.update(this, DexShotState.PHASE_ERROR, "Thiếu quyền chụp màn hình.");
            stopSelfSafely();
            return;
        }

        try {
            resolveTargetMetrics();
            MediaProjectionManager mpm = (MediaProjectionManager) getSystemService(Context.MEDIA_PROJECTION_SERVICE);
            projection = mpm.getMediaProjection(resultCode, resultData);
            projection.registerCallback(new MediaProjection.Callback() {
                @Override
                public void onStop() {
                    projectionReady = false;
                    captureRequested.set(false);
                    stopSelfSafely();
                }
            }, worker);

            imageReader = ImageReader.newInstance(width, height, PixelFormat.RGBA_8888, 3);
            imageReader.setOnImageAvailableListener(new ImageReader.OnImageAvailableListener() {
                @Override
                public void onImageAvailable(ImageReader reader) {
                    Image img = null;
                    try {
                        img = reader.acquireLatestImage();
                        if (img == null) return;
                        Bitmap bmp = imageToBitmap(img);
                        if (bmp == null) return;
                        if (captureRequested.compareAndSet(true, false)) {
                            saveAndQueue(bmp);
                        } else {
                            synchronized (frameLock) {
                                if (cachedFrame != null && !cachedFrame.isRecycled()) {
                                    cachedFrame.recycle();
                                }
                                cachedFrame = bmp;
                                lastFrameAt = System.currentTimeMillis();
                            }
                        }
                    } catch (Throwable t) {
                        Log.w(TAG, "onImageAvailable error", t);
                    } finally {
                        if (img != null) {
                            try { img.close(); } catch (Throwable ignored) {}
                        }
                    }
                }
            }, worker);

            virtualDisplay = projection.createVirtualDisplay(
                "UltraCar-DexShot",
                width,
                height,
                density,
                DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,
                imageReader.getSurface(),
                null,
                worker
            );
            projectionReady = true;

            if (intent.getBooleanExtra(EXTRA_AUTO_CAPTURE, false)) {
                worker.postDelayed(new Runnable() {
                    @Override
                    public void run() {
                        requestCapture();
                    }
                }, 250L);
            }
        } catch (Throwable t) {
            Log.e(TAG, "startProjection failed", t);
            projectionReady = false;
            DexShotState.update(this, DexShotState.PHASE_ERROR, "Không khởi tạo được chụp màn hình.");
            stopSelfSafely();
        }
    }

    private void resolveTargetMetrics() {
        DisplayManager dm = (DisplayManager) getSystemService(Context.DISPLAY_SERVICE);
        Display target = null;
        try {
            Display[] dex = dm.getDisplays(SAMSUNG_DESKTOP_CATEGORY);
            if (dex != null) {
                for (Display d : dex) {
                    if (d.getDisplayId() != 0 && d.getState() == Display.STATE_ON) {
                        target = d;
                        break;
                    }
                }
            }
        } catch (Throwable ignored) {}
        if (target == null) {
            target = dm.getDisplay(Display.DEFAULT_DISPLAY);
        }
        if (target != null) {
            DisplayMetrics metrics = new DisplayMetrics();
            target.getRealMetrics(metrics);
            width = Math.max(480, metrics.widthPixels);
            height = Math.max(360, metrics.heightPixels);
            density = Math.max(120, metrics.densityDpi);
        }
    }

    private void requestCapture() {
        if (!projectionReady) {
            captureOrRequest(this);
            return;
        }
        captureRequested.set(true);
        worker.postDelayed(new Runnable() {
            @Override
            public void run() {
                if (captureRequested.compareAndSet(true, false)) {
                    Bitmap fallback = null;
                    synchronized (frameLock) {
                        if (cachedFrame != null && !cachedFrame.isRecycled()) {
                            fallback = cachedFrame.copy(Bitmap.Config.ARGB_8888, false);
                        }
                    }
                    if (fallback != null) {
                        saveAndQueue(fallback);
                    } else {
                        mainHandler.post(new Runnable() {
                            @Override
                            public void run() {
                                DexShotState.update(DexShotCaptureService.this, DexShotState.PHASE_ERROR, "Chưa có khung hình để chụp.");
                            }
                        });
                    }
                }
            }
        }, 450L);
    }

    private Bitmap imageToBitmap(Image image) {
        Image.Plane[] planes = image.getPlanes();
        if (planes == null || planes.length == 0) return null;
        ByteBuffer buffer = planes[0].getBuffer();
        int pixelStride = planes[0].getPixelStride();
        int rowStride = planes[0].getRowStride();
        int rowPadding = rowStride - pixelStride * width;
        Bitmap raw = Bitmap.createBitmap(width + rowPadding / pixelStride, height, Bitmap.Config.ARGB_8888);
        raw.copyPixelsFromBuffer(buffer);
        if (rowPadding == 0) {
            return raw;
        }
        Bitmap cropped = Bitmap.createBitmap(raw, 0, 0, width, height);
        raw.recycle();
        return cropped;
    }

    private void saveAndQueue(Bitmap bmp) {
        try {
            DexShotQueue.enqueueBitmap(this, bmp);
            bmp.recycle();
            mainHandler.post(new Runnable() {
                @Override
                public void run() {
                    DexShotState.captured(DexShotCaptureService.this);
                    Toast.makeText(DexShotCaptureService.this, "Đã chụp màn hình · chờ 12s gửi AI", Toast.LENGTH_SHORT).show();
                }
            });
        } catch (Throwable t) {
            Log.e(TAG, "saveAndQueue failed", t);
            try { bmp.recycle(); } catch (Throwable ignored) {}
            mainHandler.post(new Runnable() {
                @Override
                public void run() {
                    DexShotState.update(DexShotCaptureService.this, DexShotState.PHASE_ERROR, "Lỗi lưu ảnh: " + t.getMessage());
                }
            });
        }
    }

    private void stopSelfSafely() {
        projectionReady = false;
        try { if (virtualDisplay != null) virtualDisplay.release(); } catch (Throwable ignored) {}
        try { if (imageReader != null) imageReader.close(); } catch (Throwable ignored) {}
        try { if (projection != null) projection.stop(); } catch (Throwable ignored) {}
        virtualDisplay = null;
        imageReader = null;
        projection = null;
        stopForeground(true);
        stopSelf();
    }

    @Override
    public void onDestroy() {
        if (activeService == this) activeService = null;
        projectionReady = false;
        synchronized (frameLock) {
            if (cachedFrame != null && !cachedFrame.isRecycled()) {
                cachedFrame.recycle();
                cachedFrame = null;
            }
        }
        if (workerThread != null) {
            try { workerThread.quitSafely(); } catch (Throwable ignored) {}
        }
        super.onDestroy();
    }

    private void ensureChannel() {
        if (Build.VERSION.SDK_INT >= 26) {
            NotificationManager nm = (NotificationManager) getSystemService(Context.NOTIFICATION_SERVICE);
            if (nm != null && nm.getNotificationChannel(CHANNEL_ID) == null) {
                NotificationChannel ch = new NotificationChannel(CHANNEL_ID, "Chụp màn hình AI", NotificationManager.IMPORTANCE_LOW);
                nm.createNotificationChannel(ch);
            }
        }
    }

    private Notification buildNotification(String text) {
        Notification.Builder b = Build.VERSION.SDK_INT >= 26
            ? new Notification.Builder(this, CHANNEL_ID)
            : new Notification.Builder(this);
        return b.setContentTitle("UltraCar AI Shot")
            .setContentText(text)
            .setSmallIcon(android.R.drawable.ic_menu_camera)
            .setOngoing(true)
            .build();
    }
}

package com.tigeriq.dexshot;

import android.app.Activity;
import android.content.Context;
import android.content.Intent;
import android.media.projection.MediaProjectionManager;
import android.os.Build;
import android.os.Bundle;
import android.widget.Toast;

public final class DexShotProjectionActivity extends Activity {
    private static final int REQ_MEDIA_PROJECTION = 4201;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        try {
            MediaProjectionManager mpm = (MediaProjectionManager) getSystemService(Context.MEDIA_PROJECTION_SERVICE);
            startActivityForResult(mpm.createScreenCaptureIntent(), REQ_MEDIA_PROJECTION);
        } catch (Throwable t) {
            Toast.makeText(this, "Không mở được quyền chụp màn hình.", Toast.LENGTH_SHORT).show();
            finish();
        }
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (requestCode == REQ_MEDIA_PROJECTION) {
            if (resultCode == RESULT_OK && data != null) {
                Intent svc = new Intent(this, DexShotCaptureService.class);
                svc.setAction(DexShotCaptureService.ACTION_START);
                svc.putExtra(DexShotCaptureService.EXTRA_RESULT_CODE, resultCode);
                svc.putExtra(DexShotCaptureService.EXTRA_RESULT_DATA, data);
                svc.putExtra(DexShotCaptureService.EXTRA_AUTO_CAPTURE, true);
                if (Build.VERSION.SDK_INT >= 26) {
                    startForegroundService(svc);
                } else {
                    startService(svc);
                }
            } else {
                DexShotState.update(this, DexShotState.PHASE_ERROR, "Chưa cấp quyền chụp màn hình.");
            }
        }
        finish();
    }
}

package com.tigeriq.camera;

import android.content.Context;
import android.content.Intent;
import android.content.SharedPreferences;
import android.media.session.MediaSession;
import android.media.session.PlaybackState;
import android.os.Handler;
import android.os.Looper;
import android.os.SystemClock;
import android.util.Log;
import android.view.KeyEvent;
import com.tigeriq.dexshot.DexShotCaptureService;
import com.ultracar.dexsplit.ui.TigerIQBridge;

public final class BluetoothMediaButtonHub {
    private static final String TAG = "UltraCarBT";
    private static final Handler MAIN = new Handler(Looper.getMainLooper());
    private static MediaSession mediaSession;
    private static Context appContext;
    private static volatile boolean active = false;

    private static Runnable pendingHoldRunnable;
    private static boolean holdTriggered = false;
    private static long lastDexShotAt = 0L;

    private BluetoothMediaButtonHub() {}

    public static boolean isActive() {
        return active && mediaSession != null;
    }

    public static synchronized void start(Context context) {
        if (context == null) return;
        appContext = context.getApplicationContext();
        if (mediaSession != null) {
            try {
                mediaSession.setActive(true);
                active = true;
            } catch (Throwable ignored) {}
            return;
        }
        try {
            MediaSession session = new MediaSession(appContext, "UltraCarRemoteBT");
            session.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS | MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);
            PlaybackState state = new PlaybackState.Builder()
                .setActions(
                    PlaybackState.ACTION_PLAY
                    | PlaybackState.ACTION_PAUSE
                    | PlaybackState.ACTION_PLAY_PAUSE
                    | PlaybackState.ACTION_SKIP_TO_PREVIOUS
                    | PlaybackState.ACTION_SKIP_TO_NEXT
                )
                .setState(PlaybackState.STATE_PAUSED, 0L, 1.0f)
                .build();
            session.setPlaybackState(state);
            session.setCallback(new MediaSession.Callback() {
                @Override
                public boolean onMediaButtonEvent(Intent mediaButtonIntent) {
                    if (mediaButtonIntent != null) {
                        KeyEvent ke = mediaButtonIntent.getParcelableExtra(Intent.EXTRA_KEY_EVENT);
                        if (ke != null && handleKeyEvent(ke)) {
                            return true;
                        }
                    }
                    return super.onMediaButtonEvent(mediaButtonIntent);
                }

                @Override
                public void onSkipToPrevious() {
                    triggerDexShot();
                }
            }, MAIN);
            session.setActive(true);
            mediaSession = session;
            active = true;
            Log.i(TAG, "BluetoothMediaButtonHub started (MediaSession active, no Accessibility)");
        } catch (Throwable t) {
            Log.e(TAG, "Failed to start MediaSession", t);
            active = false;
        }
    }

    public static synchronized void stop() {
        active = false;
        cancelHold();
        if (mediaSession != null) {
            try {
                mediaSession.setActive(false);
                mediaSession.release();
            } catch (Throwable ignored) {}
            mediaSession = null;
        }
    }

    private static boolean handleKeyEvent(KeyEvent ke) {
        if (appContext == null || ke == null) return false;
        int code = ke.getKeyCode();
        int action = ke.getAction();
        int repeat = ke.getRepeatCount();

        int configuredCamKey = RemoteKeyPrefs.getKeyCode(appContext);
        boolean isPlayKey = (code == configuredCamKey)
            || code == KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE
            || code == KeyEvent.KEYCODE_MEDIA_PLAY
            || code == KeyEvent.KEYCODE_MEDIA_PAUSE
            || code == KeyEvent.KEYCODE_HEADSETHOOK;

        SharedPreferences sp = appContext.getSharedPreferences("tigeriq_remote_shortcut", Context.MODE_PRIVATE);
        int dexShotKey = sp.getInt("dexshot_key_code", KeyEvent.KEYCODE_MEDIA_PREVIOUS);
        boolean isDexShotKey = (code == dexShotKey || code == KeyEvent.KEYCODE_MEDIA_PREVIOUS);

        if (isDexShotKey) {
            if (action == KeyEvent.ACTION_DOWN && repeat == 0) {
                triggerDexShot();
            }
            return true;
        }

        if (isPlayKey && RemoteKeyPrefs.isEnabled(appContext)) {
            if (action == KeyEvent.ACTION_DOWN && repeat == 0) {
                holdTriggered = false;
                cancelHold();
                long holdMs = Math.max(250L, RemoteKeyPrefs.getHoldMs(appContext));
                pendingHoldRunnable = new Runnable() {
                    @Override
                    public void run() {
                        holdTriggered = true;
                        pendingHoldRunnable = null;
                        try {
                            TigerIQBridge.toggleCamera();
                        } catch (Throwable t) {
                            Log.w(TAG, "toggleCamera failed", t);
                        }
                    }
                };
                MAIN.postDelayed(pendingHoldRunnable, holdMs);
                return true;
            } else if (action == KeyEvent.ACTION_UP || ke.isCanceled()) {
                cancelHold();
                return holdTriggered;
            }
            return true;
        }
        return false;
    }

    private static void triggerDexShot() {
        long now = SystemClock.uptimeMillis();
        if (now - lastDexShotAt < 450L) return;
        lastDexShotAt = now;
        if (appContext != null) {
            MAIN.post(new Runnable() {
                @Override
                public void run() {
                    try {
                        DexShotCaptureService.captureOrRequest(appContext);
                    } catch (Throwable t) {
                        Log.w(TAG, "triggerDexShot failed", t);
                    }
                }
            });
        }
    }

    private static void cancelHold() {
        if (pendingHoldRunnable != null) {
            MAIN.removeCallbacks(pendingHoldRunnable);
            pendingHoldRunnable = null;
        }
    }
}

package com.tigeriq.camera;

import android.graphics.Canvas;
import android.graphics.Paint;
import android.graphics.Path;
import android.graphics.RectF;

public final class FloatingCarRearIcon {
    private FloatingCarRearIcon() {}

    public static void draw(Canvas canvas, Paint paint, int width, int height, boolean active) {
        if (canvas == null || paint == null || width <= 0 || height <= 0) {
            return;
        }
        float w = (float) width;
        float h = (float) height;
        float minDim = Math.min(w, h);
        // Inset ~6.8% on each side so 44dp slot renders a 38dp rounded-square icon matching other app icons
        float pad = minDim * 0.068f;
        float left = (w - minDim) * 0.5f + pad;
        float top = (h - minDim) * 0.5f + pad;
        float size = minDim - (pad * 2.0f);
        float right = left + size;
        float bottom = top + size;
        float cornerRadius = size * 0.22f;
        RectF bgRect = new RectF(left, top, right, bottom);

        paint.reset();
        paint.setAntiAlias(true);
        paint.setStyle(Paint.Style.FILL);
        paint.setColor(active ? 0xE60B2E3C : 0xCC182028);
        canvas.drawRoundRect(bgRect, cornerRadius, cornerRadius, paint);

        paint.setStyle(Paint.Style.STROKE);
        paint.setColor(active ? 0xFF00E5F6 : 0xCC7B8A9E);
        paint.setStrokeWidth(Math.max(2.5f, size * (active ? 0.052f : 0.036f)));
        canvas.drawRoundRect(bgRect, cornerRadius, cornerRadius, paint);

        // Car rear illustration inside bgRect
        float cx = left + size * 0.46f;
        float carTop = top + size * 0.28f;
        float carBot = top + size * 0.80f;
        float carH = carBot - carTop;
        float carW = size * 0.56f;
        float roofW = size * 0.36f;

        int bodyColor = active ? 0xFFFFFFFF : 0xCCCAD2DA;
        int glassColor = active ? 0xFF0E2338 : 0xFF242B32;
        int tailColor = active ? 0xFFFF2244 : 0xFF69727A;
        int tailInner = active ? 0xFFFF96A8 : 0xFF8A929B;

        paint.setStyle(Paint.Style.FILL);
        paint.setColor(bodyColor);

        float wheelW = carW * 0.18f;
        float wheelTop = carBot - (carH * 0.24f * 0.7f);
        float halfWheelSpan = carW * 0.45f;
        float wheelL = cx - halfWheelSpan;
        float wheelR = cx + halfWheelSpan;
        float wheelRRadius = size * 0.03f;
        float wheelBot = carBot + (carH * 0.03f);
        canvas.drawRoundRect(new RectF(wheelL, wheelTop, wheelL + wheelW, wheelBot), wheelRRadius, wheelRRadius, paint);
        canvas.drawRoundRect(new RectF(wheelR - wheelW, wheelTop, wheelR, wheelBot), wheelRRadius, wheelRRadius, paint);

        float waistY = (0.42f * carH) + carTop;
        float mirrorR = size * 0.02f;
        float mirrorOuter = 0.54f * carW;
        float mirrorHalfH = 0.055f * carH;
        float mirrorInner = 0.41f * carW;
        canvas.drawRoundRect(new RectF(cx - mirrorOuter, waistY - mirrorHalfH, cx - mirrorInner, waistY + mirrorHalfH), mirrorR, mirrorR, paint);
        canvas.drawRoundRect(new RectF(cx + mirrorInner, waistY - mirrorHalfH, cx + mirrorOuter, waistY + mirrorHalfH), mirrorR, mirrorR, paint);

        Path cabin = new Path();
        float roofHalf = roofW * 0.44f;
        float cabinHalf = 0.44f * carW;
        cabin.moveTo(cx - roofHalf, carTop);
        cabin.lineTo(cx + roofHalf, carTop);
        cabin.lineTo(cx + cabinHalf, waistY + 0.04f * carH);
        cabin.lineTo(cx - cabinHalf, waistY + 0.04f * carH);
        cabin.close();
        canvas.drawPath(cabin, paint);

        Path glass = new Path();
        float gTopHalf = 0.35f * roofW;
        float gBotHalf = 0.33f * carW;
        float gTopY = carTop + 0.09f * carH;
        float gBotY = waistY - 0.02f * carH;
        glass.moveTo(cx - gTopHalf, gTopY);
        glass.lineTo(cx + gTopHalf, gTopY);
        glass.lineTo(cx + gBotHalf, gBotY);
        glass.lineTo(cx - gBotHalf, gBotY);
        glass.close();
        paint.setColor(glassColor);
        canvas.drawPath(glass, paint);

        float bodyBot = carBot - 0.12f * carH;
        paint.setColor(bodyColor);
        float bodyRadius = size * 0.055f;
        canvas.drawRoundRect(new RectF(cx - carW * 0.5f, waistY, cx + carW * 0.5f, bodyBot), bodyRadius, bodyRadius, paint);

        float lightTop = waistY + 0.08f * carH;
        float lightBot = waistY + 0.21f * carH;
        paint.setColor(tailColor);
        float lightInner = 0.16f * carW;
        canvas.drawRoundRect(new RectF(wheelL, lightTop, cx - lightInner, lightBot), mirrorR, mirrorR, paint);
        canvas.drawRoundRect(new RectF(cx + lightInner, lightTop, wheelR, lightBot), mirrorR, mirrorR, paint);

        paint.setStyle(Paint.Style.STROKE);
        paint.setStrokeWidth(Math.max(2.0f, 0.018f * size));
        paint.setStrokeCap(Paint.Cap.ROUND);
        paint.setStrokeJoin(Paint.Join.ROUND);
        Path trunkLine = new Path();
        float midLightY = (lightTop + lightBot) * 0.5f;
        float trunkHalf = 0.17f * carW;
        trunkLine.moveTo(cx - trunkHalf, midLightY);
        trunkLine.lineTo(cx, waistY + 0.2f * carH);
        trunkLine.lineTo(cx + trunkHalf, midLightY);
        canvas.drawPath(trunkLine, paint);

        paint.setStyle(Paint.Style.FILL);
        paint.setColor(tailInner);
        float padLightY = (lightBot - lightTop) * 0.26f;
        float padLightX = 0.014f * size;
        float innerR = 0.012f * size;
        canvas.drawRoundRect(new RectF(wheelL + padLightX, lightTop + padLightY, cx - 0.19f * carW, lightBot - padLightY), innerR, innerR, paint);
        canvas.drawRoundRect(new RectF(cx + 0.19f * carW, lightTop + padLightY, wheelR - padLightX, lightBot - padLightY), innerR, innerR, paint);

        paint.setColor(glassColor);
        float plateHalf = carW * 0.13f;
        canvas.drawRoundRect(new RectF(cx - plateHalf, lightBot, cx + plateHalf, waistY + 0.33f * carH), 2.0f, 2.0f, paint);

        // 'R' badge at top-right inside rounded square
        float badgeX = left + size * 0.77f;
        float badgeY = top + size * 0.23f;
        float badgeR = size * 0.145f;
        paint.setColor(active ? 0xFFFF1744 : 0xDD4C5663);
        canvas.drawCircle(badgeX, badgeY, badgeR, paint);
        paint.setColor(active ? 0xFFFFFFFF : 0xDDDADEE2);
        paint.setTextSize(size * 0.21f);
        paint.setFakeBoldText(true);
        paint.setTextAlign(Paint.Align.CENTER);
        Paint.FontMetrics fm = paint.getFontMetrics();
        canvas.drawText("R", badgeX, badgeY - ((fm.ascent + fm.descent) * 0.5f), paint);
    }
}

package com.tigeriq.v44;

import android.content.Context;
import android.content.Intent;
import android.graphics.Canvas;
import android.graphics.Paint;
import android.graphics.RectF;
import android.graphics.Typeface;
import android.graphics.drawable.Drawable;
import android.os.Handler;
import android.os.Looper;
import android.os.SystemClock;
import android.view.MotionEvent;
import android.view.View;
import android.widget.Toast;
import com.tigeriq.dexshot.DexShotCaptureService;
import com.tigeriq.dexshot.DexShotLoginActivity;
import com.tigeriq.dexshot.DexShotState;
import com.tigeriq.dexshot.DexShotUploader;

public final class DexShotQuickButton extends View implements DexShotState.Listener {
    private static final Handler MAIN = new Handler(Looper.getMainLooper());
    private final Drawable icon;
    private final Paint paint = new Paint(1);
    private final float density;
    private long downAt = 0L;
    private boolean longTriggered = false;

    private final Runnable animTick = new Runnable() {
        @Override
        public void run() {
            if (isAttachedToWindow()) {
                invalidate();
                if (DexShotState.getPhase() != DexShotState.PHASE_READY) {
                    postDelayed(this, 70L);
                }
            }
        }
    };

    private final Runnable longPressTask = new Runnable() {
        @Override
        public void run() {
            longTriggered = true;
            Context ctx = getContext();
            if (ctx == null) return;
            if (!DexShotUploader.hasSessionCookie() || DexShotState.getPhase() == DexShotState.PHASE_ERROR) {
                Intent login = new Intent(ctx, DexShotLoginActivity.class);
                login.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
                ctx.startActivity(login);
                return;
            }
            String msg = DexShotState.getMessage();
            if (msg == null || msg.trim().isEmpty()) {
                msg = DexShotState.getPhase() == DexShotState.PHASE_READY
                    ? "Nút T DeX sẵn sàng. Chạm nhanh để chụp AI."
                    : "Ảnh DeX đang xử lý...";
            }
            Toast.makeText(ctx, msg, Toast.LENGTH_LONG).show();
        }
    };

    public DexShotQuickButton(Context context) {
        super(context);
        this.density = context.getResources().getDisplayMetrics().density;
        Drawable d = null;
        try {
            int resId = context.getResources().getIdentifier("tigeriq_capture_icon", "drawable", context.getPackageName());
            if (resId != 0) {
                d = context.getResources().getDrawable(resId, context.getTheme());
                if (d != null) d = d.mutate();
            }
        } catch (Throwable ignored) {}
        this.icon = d;

        setContentDescription("TigerIQ Driver T · chụp ảnh AI");
        setClickable(true);
        setFocusable(true);
        setOnTouchListener(new OnTouchListener() {
            @Override
            public boolean onTouch(View v, MotionEvent ev) {
                int action = ev.getAction();
                if (action == MotionEvent.ACTION_DOWN) {
                    downAt = SystemClock.uptimeMillis();
                    longTriggered = false;
                    MAIN.removeCallbacks(longPressTask);
                    MAIN.postDelayed(longPressTask, 650L);
                    return true;
                }
                if (action == MotionEvent.ACTION_UP) {
                    MAIN.removeCallbacks(longPressTask);
                    if (!longTriggered && SystemClock.uptimeMillis() - downAt < 650L) {
                        onQuickTap();
                    }
                    return true;
                }
                if (action == MotionEvent.ACTION_CANCEL) {
                    MAIN.removeCallbacks(longPressTask);
                    return false;
                }
                return false;
            }
        });
    }

    private void onQuickTap() {
        Context ctx = getContext();
        if (ctx != null) {
            DexShotCaptureService.captureOrRequest(ctx);
        }
    }

    @Override
    public void onStateChanged() {
        invalidate();
        removeCallbacks(animTick);
        if (isAttachedToWindow()) {
            post(animTick);
        }
    }

    @Override
    protected void onAttachedToWindow() {
        super.onAttachedToWindow();
        DexShotState.bind(this);
        removeCallbacks(animTick);
        post(animTick);
    }

    @Override
    protected void onDetachedFromWindow() {
        removeCallbacks(animTick);
        DexShotState.unbind(this);
        super.onDetachedFromWindow();
    }

    @Override
    protected void onDraw(Canvas canvas) {
        super.onDraw(canvas);
        float w = getWidth();
        float h = getHeight();
        float minDim = Math.min(w, h);
        if (minDim <= 0.0f) return;

        // Match 38dp icon inside 44dp slot (~6.8% inset)
        float pad = minDim * 0.068f;
        int left = Math.round((w - minDim) * 0.5f + pad);
        int top = Math.round((h - minDim) * 0.5f + pad);
        int size = Math.round(minDim - pad * 2.0f);
        if (icon != null) {
            icon.setBounds(left, top, left + size, top + size);
            icon.draw(canvas);
        }

        int phase = DexShotState.getPhase();
        if (phase == DexShotState.PHASE_READY) {
            return;
        }

        float cx = w * 0.5f;
        float cy = h * 0.5f;
        float r = 0.38f * minDim;
        paint.reset();
        paint.setAntiAlias(true);
        paint.setStyle(Paint.Style.FILL);
        paint.setColor(0xE508191C);
        canvas.drawCircle(cx, cy, r, paint);

        float sec = SystemClock.uptimeMillis() / 1000.0f;
        if (phase == DexShotState.PHASE_UPLOADING || phase == DexShotState.PHASE_PROCESSING) {
            float pulse = (float) Math.sin(sec * 4.5d) * 0.5f + 0.5f;
            float r1 = 0.89f * r;
            RectF rect1 = new RectF(cx - r1, cy - r1, cx + r1, cy + r1);
            float r2 = 0.69f * r;
            RectF rect2 = new RectF(cx - r2, cy - r2, cx + r2, cy + r2);

            paint.setStyle(Paint.Style.STROKE);
            paint.setStrokeCap(Paint.Cap.ROUND);
            paint.setStrokeWidth(density * 2.0f);
            paint.setColor(0x3867E8F9);
            canvas.drawCircle(cx, cy, r1, paint);

            paint.setColor(0xFF4DFFAE);
            paint.setStrokeWidth(((0.9f * pulse) + 2.5f) * density);
            canvas.drawArc(rect1, (170.0f * sec) % 360.0f, (pulse * 75.0f) + 100.0f, false, paint);

            paint.setColor(0xFF93FFC9);
            paint.setStrokeWidth(density * 1.5f);
            canvas.drawArc(rect2, 350.0f - ((sec * 112.0f) % 360.0f), 65.0f, false, paint);

            paint.setStyle(Paint.Style.FILL);
            paint.setColor(0xFFB7FFDB);
            paint.setTypeface(Typeface.create(Typeface.DEFAULT, Typeface.BOLD));
            paint.setTextAlign(Paint.Align.CENTER);
            paint.setTextSize(minDim * 0.2f);
            canvas.drawText(phase == DexShotState.PHASE_UPLOADING ? "↑" : "AI", cx, cy - ((paint.ascent() + paint.descent()) * 0.5f), paint);
            return;
        }

        paint.setTextAlign(Paint.Align.CENTER);
        paint.setTypeface(Typeface.create(Typeface.DEFAULT, Typeface.BOLD));
        paint.setColor(0xFFFFFFFF);
        if (phase == DexShotState.PHASE_COUNTDOWN) {
            int rem = (int) Math.ceil(Math.max(DexShotState.getDeadlineAt() - System.currentTimeMillis(), 0L) / 1000.0d);
            paint.setTextSize(minDim * 0.36f);
            canvas.drawText(String.valueOf(rem), cx, cy - ((paint.ascent() + paint.descent()) * 0.5f), paint);
            return;
        }
        if (phase == DexShotState.PHASE_COMPLETE) {
            paint.setColor(0xFFBAFFC9);
            paint.setTextSize(minDim * 0.43f);
            canvas.drawText("✓", cx, cy - ((paint.ascent() + paint.descent()) * 0.5f), paint);
            return;
        }
        if (phase == DexShotState.PHASE_REVIEW || phase == DexShotState.PHASE_ERROR) {
            boolean isReview = (phase == DexShotState.PHASE_REVIEW);
            paint.setColor(isReview ? 0xFFFFDF95 : 0xFFFFA780);
            paint.setStyle(Paint.Style.STROKE);
            paint.setStrokeWidth(density * 2.0f);
            float rArc = r * 0.8f;
            canvas.drawArc(new RectF(cx - rArc, cy - rArc, cx + rArc, cy + rArc), 208.0f, 124.0f, false, paint);
            paint.setStyle(Paint.Style.FILL);
            String label = "!";
            if (isReview) {
                String msg = DexShotState.getMessage();
                String lower = msg != null ? msg.toLowerCase() : "";
                if (lower.contains("mã cuốc")) label = "MÃ";
                else if (lower.contains("ca sơn")) label = "CA";
                else if (lower.contains("hoàn tất")) label = "XONG";
                else label = "ẢNH";
            }
            paint.setTextSize(minDim * (isReview ? 0.19f : 0.34f));
            canvas.drawText(label, cx, cy - ((paint.ascent() + paint.descent()) * 0.5f), paint);
        }
    }
}

